// Format Shortlist JSON payload into HTML report string
const body = $input.item.json.body || $input.item.json;
const items = body.shortlist || [];

const itemsHtml = items.map((item, idx) => `
  <div style="background:#0f172a; border:1px solid #1e293b; border-radius:12px; padding:18px; margin-bottom:16px;">
    <h3 style="color:#38bdf8; margin:0 0 8px;">#${idx + 1}. ${item.title}</h3>
    <p style="color:#cbd5e1; margin:4px 0;">📍 Locality: ${item.area}, Bengaluru</p>
    <p style="color:#2dd4bf; font-weight:bold; margin:4px 0;">₹${(item.rent || 0).toLocaleString('en-IN')}/mo (${item.bedrooms} BHK)</p>
  </div>
`).join('');

return [{
  json: {
    buyerEmail: body.buyerEmail,
    buyerName: body.buyerName || 'Scout Renter',
    htmlReport: itemsHtml,
    listingCount: items.length
  }
}];
